------------ LifeCycle ------------
function UIBattlingWorldBossStartDialog:__init()
    self.listCardHead = nil
    self.battleWaveNow = nil
    self.teamIndex = nil
end

function UIBattlingWorldBossStartDialog:__delete()
    self.listCardHead = nil
    self.battleWaveNow = nil
    self.teamIndex = nil
    self.controller = nil
end

function UIBattlingWorldBossStartDialog:Awake()
    if not IsNull(self.TxtCountdown) then
        KTool.SetActive(self.TxtCountdown.gameObject, false)
    end
end

function UIBattlingWorldBossStartDialog:OnInitialize()
    xTry(function()
        self.battleWaveNow = UIBattlingCtrlMgr:GetInstance():GetBattleWave(BattleInfo.myCamp)
        self:FillCardHead()
        self:SetPlayerTeam()
        self:SetWaveNum()
    end)
end

function UIBattlingWorldBossStartDialog:OnShow()
    local coWait = CoWait.Start():Coroutine(
            util.cs_generator(
                    function()
                        coroutine.yield(Yielders.GetWaitForSeconds(3))
                        UIModule.CloseDialog(self.controller)
                    end
            )
    )
    return coWait
end

function UIBattlingWorldBossStartDialog:OnFinalize()
    xTry(function()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
