function UIBattlingWorldBossStartDialog:FillCardHead()
    self.listCardHead = {}
    table.insert(self.listCardHead, self.CommonSmallHeadNode_1)
    table.insert(self.listCardHead, self.CommonSmallHeadNode_2)
    table.insert(self.listCardHead, self.CommonSmallHeadNode_3)
    table.insert(self.listCardHead, self.CommonSmallHeadNode_4)
end

---SetPlayerTeam
function UIBattlingWorldBossStartDialog:SetPlayerTeam()
    --TODO 波次队伍数据
    local teamData = UIBattlingDataMgr:GetPlayerTeamList(self.battleWaveNow)
    for i = 1, #self.listCardHead do
        if i <= #teamData then
            local goNode = self.listCardHead[i].gameObject
            local lbCardNode = self.listCardHead[i]
            if lbCardNode then
                lbCardNode:Init()
                local cardNode = lbCardNode.Env
                if cardNode then
                    self:SetCardNode(cardNode, teamData[i])
                    KTool.SetActive(goNode, true)
                end
            end
        end
    end
end

---SetCardNode
---@param cardNode CardHeadNode
---@param cardData table
function UIBattlingWorldBossStartDialog:SetCardNode(cardNode, cardData)
    if IsNull(cardNode) or IsNull(cardData) then return end
    local cardComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.CardComponent)
    local cardDojo = cardComp:GetCardById(cardData.playerCardId)
    cardNode:FreshNode(cardDojo, false, nil)
end

---SetWaveNum
function UIBattlingWorldBossStartDialog:SetWaveNum()
    local curQuestId = UIBattlingDataMgr:GetQuestId()
    local teamData = UIBattlingDataMgr:GetPlayerTeamList(self.battleWaveNow)
    local roleData = teamData[1]
    local keyPlayerCardId = roleData and roleData.playerCardId or 0 
    local teamComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.TeamComponent)
    local teamIndex = teamComp:GetTeamIndexById(curQuestId, keyPlayerCardId)
    --print("->UIBattlingWorldBossStartDialog:SetWaveNum", teamIndex)
    if self.TxtNum and teamIndex then
        self.TxtNum.text = tostring(teamIndex)
    end
end
